python3 -c "
import json
# check duplicate key detection with object_pairs_hook, parse_constant, huge ints
def strict(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
print(json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=strict))
try:
    json.loads('\"x\":1e400', object_pairs_hook=strict)
    print('1e400 ->', )
except Exception as e: print('err',e)
print(json.loads('1e400'))
try:
    json.loads('1'+'0'*5000)
except Exception as e: print('huge int err:', type(e).__name__, str(e)[:60])
print(json.loads('{"a":NaN}', parse_constant=lambda x: (_ for _ in ()).throw(ValueError('nonfinite'))))
"
